CREATE VIEW problem_decomposition.v_costs AS
 SELECT 'Decomposition'::text AS type,
    tasks.user_id,
    sum(tasks.tokens_in) AS tokens_in,
    sum(tasks.tokens_out) AS tokens_out,
    (((sum(tasks.tokens_in) / (1000000)::numeric) * 0.50) + ((sum(tasks.tokens_out) / (1000000)::numeric) * 1.50)) AS cost
   FROM problem_decomposition.tasks
  GROUP BY tasks.user_id
UNION ALL
 SELECT 'Implementation'::text AS type,
    implementations.user_id,
    sum(implementations.tokens_in) AS tokens_in,
    sum(implementations.tokens_out) AS tokens_out,
    (((sum(implementations.tokens_in) / (1000000)::numeric) * 0.50) + ((sum(implementations.tokens_out) / (1000000)::numeric) * 1.50)) AS cost
   FROM problem_decomposition.implementations
  GROUP BY implementations.user_id;


