CREATE VIEW problem_decomposition.v_leaderboard AS
 SELECT dense_rank() OVER (ORDER BY credits DESC) AS rank,
    user_id,
    credits,
    feedback_given,
    feedback_received,
    feedback_excellent,
    feedback_good,
    correct_guesses
   FROM problem_decomposition.users
  ORDER BY (dense_rank() OVER (ORDER BY credits DESC));


