--
-- Name: v_tree_summary; Type: VIEW; Schema: problem_decomposition; Owner: postgres
--

CREATE VIEW problem_decomposition.v_tree_summary AS
 SELECT t.tree_id,
    t.user_id,
    tasks.solved,
        CASE
            WHEN (length((tasks.name)::text) > 50) THEN ((SUBSTRING(tasks.name FROM 1 FOR 50) || '...'::text))::character varying
            ELSE tasks.name
        END AS name
   FROM (problem_decomposition.trees t
     JOIN problem_decomposition.tasks USING (tree_id))
  WHERE (tasks.parent_id IS NULL)
  ORDER BY t.tree_id;


