--
-- Name: v_trees; Type: VIEW; Schema: problem_decomposition; Owner: postgres
--

CREATE VIEW problem_decomposition.v_trees AS
 WITH RECURSIVE tree_cte AS (
         SELECT tasks.task_id,
            tasks.parent_id,
            tasks.tree_id,
            tasks.user_id,
            tasks.creation_mode,
            tasks.name,
            tasks.description,
            tasks.solved,
            0 AS level,
            ARRAY[]::numeric[] AS path
           FROM problem_decomposition.tasks
          WHERE (tasks.parent_id IS NULL)
        UNION ALL
         SELECT t_1.task_id,
            t_1.parent_id,
            t_1.tree_id,
            t_1.user_id,
            t_1.creation_mode,
            t_1.name,
            t_1.description,
            t_1.solved,
            (cte.level + 1),
            (cte.path || t_1.order_n)
           FROM (problem_decomposition.tasks t_1
             JOIN tree_cte cte ON ((t_1.parent_id = cte.task_id)))
          WHERE (t_1.deleted = false)
        )
 SELECT t.tree_id,
    t.path,
    t.level,
    t.task_id,
    t.parent_id,
    t.user_id AS task_user_id,
    i.user_id AS implementation_user_id,
    t.creation_mode,
    t.solved,
    t.name,
    t.description,
    i.implementation_id,
    i.implementation,
    i.implementation_language
   FROM (tree_cte t
     LEFT JOIN problem_decomposition.implementations i ON (((i.task_id = t.task_id) AND ((i.deleted = false) OR (i.deleted IS NULL)))))
  ORDER BY t.tree_id, t.path;


ALTER VIEW problem_decomposition.v_trees OWNER TO postgres;

